import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.MultiPlayerSettings{ActionType: packet.RefreshJoinCode}
REFRESH_JOINCODE = bytes.fromhex("04")

# generated by gophertunnel b8bd735:
# &packet.MultiPlayerSettings{ActionType: packet.DisableMultiPlayer}
DISABLE_MULTIPLAYER = bytes.fromhex("02")

GOLDENS = [
    pytest.param(
        v2225.MultiplayerSettingsPacket(packet_type=v2225.MultiplayerSettingsPacketType.REFRESH_JOINCODE),
        REFRESH_JOINCODE,
        id="refresh-joincode",
    ),
    pytest.param(
        v2225.MultiplayerSettingsPacket(packet_type=v2225.MultiplayerSettingsPacketType.DISABLE_MULTIPLAYER),
        DISABLE_MULTIPLAYER,
        id="disable-multiplayer",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_multiplayer_settings_is_packet_139(version):
    assert version.PACKETS[139] is version.MultiplayerSettingsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_multiplayer_settings_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_multiplayer_settings_decodes_from_its_golden(packet, golden):
    assert v2225.MultiplayerSettingsPacket.from_bytes(golden) == packet


def test_multiplayer_settings_type_is_not_a_fixed_int32():
    with pytest.raises(ValueError, match="trailing bytes"):
        v2225.MultiplayerSettingsPacket.from_bytes(bytes.fromhex("02000000"))
